// n8n Code node (JavaScript)
// Assumes your JSON array is in items[0].json.payload as a string or object.
// You can adjust `const rawPayload = ...` if your field name is different.

const rawPayload = items[0].json.payload ?? items[0].json.data ?? items[0].json;

// Ensure we have an array of objects
let enquiries;
if (typeof rawPayload === 'string') {
  enquiries = JSON.parse(rawPayload);
} else if (Array.isArray(rawPayload)) {
  enquiries = rawPayload;
} else {
  throw new Error('$input.first().json.data');
}

if (!enquiries.length) {
  throw new Error('No enquiry records found in payload.');
}

// Pick the latest enquiry by createdAt (fallback to highest id)
const latest = enquiries.reduce((latestSoFar, current) => {
  if (!latestSoFar) return current;
  const latestDate = new Date(latestSoFar.createdAt || 0);
  const currentDate = new Date(current.createdAt || 0);

  if (currentDate > latestDate) return current;

  // Fallback if dates are equal/invalid: use highest id
  if (currentDate.getTime() === latestDate.getTime()) {
    return (current.id || 0) > (latestSoFar.id || 0) ? current : latestSoFar;
  }

  return latestSoFar;
}, null);

// Extract fields
const {
  user_name,
  user_email,
  source,
  q1_business_overview,
  q2_daily_workflow,
  q3_bottlenecks,
  q4_systems_tools,
  q5_desired_outcomes,
  createdAt,
} = latest;

// Friendly name for report recipient
const reportRecipientName = 'John Saenz';

// Format created date nicely
let createdDateDisplay = '';
try {
  const d = new Date(createdAt);
  createdDateDisplay = d.toLocaleString('en-AU', {
    timeZone: 'Australia/Sydney',
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
} catch (e) {
  createdDateDisplay = createdAt || '';
}

const subject = `New web enquiry from ${user_name || 'prospect'} via ${source || 'website chat'}`;

// Build professional HTML email body
const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>${subject}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <style>
    /* Basic reset */
    body {
      margin: 0;
      padding: 0;
      background-color: #f3f4f6;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
      color: #111827;
    }
    .wrapper {
      width: 100%;
      padding: 24px 12px;
      box-sizing: border-box;
    }
    .container {
      max-width: 720px;
      margin: 0 auto;
      background-color: #ffffff;
      border-radius: 12px;
      box-shadow: 0 10px 30px rgba(15, 23, 42, 0.12);
      overflow: hidden;
      border: 1px solid #e5e7eb;
    }
    .header {
      background: linear-gradient(135deg, #2563eb, #0ea5e9);
      color: #ffffff;
      padding: 24px 28px;
    }
    .header h1 {
      margin: 0;
      font-size: 22px;
      font-weight: 600;
      letter-spacing: 0.02em;
    }
    .header p {
      margin: 8px 0 0;
      font-size: 14px;
      opacity: 0.9;
    }
    .content {
      padding: 24px 28px 28px;
    }
    .greeting {
      font-size: 15px;
      margin-bottom: 16px;
    }
    .meta {
      font-size: 13px;
      color: #6b7280;
      margin-bottom: 20px;
    }
    .meta strong {
      color: #374151;
    }
    .section {
      margin-bottom: 18px;
      padding: 14px 16px;
      border-radius: 10px;
      background-color: #f9fafb;
      border: 1px solid #e5e7eb;
    }
    .section h2 {
      margin: 0 0 8px;
      font-size: 14px;
      font-weight: 600;
      color: #111827;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .section p {
      margin: 0;
      font-size: 14px;
      line-height: 1.6;
      color: #374151;
    }
    .section p span.label {
      font-weight: 600;
      color: #111827;
    }
    .pill-row {
      margin-top: 6px;
      font-size: 12px;
      color: #6b7280;
    }
    .pill {
      display: inline-block;
      margin-right: 6px;
      margin-top: 4px;
      padding: 4px 10px;
      border-radius: 999px;
      background-color: #e5f0ff;
      color: #1d4ed8;
      font-weight: 500;
    }
    .footer {
      border-top: 1px solid #e5e7eb;
      padding-top: 16px;
      margin-top: 8px;
      font-size: 12px;
      color: #6b7280;
    }
    .footer p {
      margin: 4px 0;
    }
    .footer a {
      color: #2563eb;
      text-decoration: none;
    }
    .footer a:hover {
      text-decoration: underline;
    }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="container">
      <div class="header">
        <h1>New Web Enquiry – ClinicIQ Solutions</h1>
        <p>Summary of the latest conversation captured from the website chat.</p>
      </div>
      <div class="content">
        <p class="greeting">Hi ${reportRecipientName},</p>
        <p class="greeting">
          A new enquiry has been received via <strong>${source || 'ClinicIQ Solutions Chat'}</strong>.
          Below is a structured summary of the enquiry and their workflow.
        </p>

        <div class="meta">
          <p><strong>Lead name:</strong> ${user_name || 'N/A'}</p>
          <p><strong>Email:</strong> <a href="mailto:${user_email}" style="color:#2563eb;text-decoration:none;">${user_email}</a></p>
          ${createdDateDisplay ? `<p><strong>Enquiry time:</strong> ${createdDateDisplay}</p>` : ''}
          <p><strong>Conversation ID:</strong> ${latest.conversation_id || 'N/A'}</p>
        </div>

        <div class="section">
          <h2>Role & Clinic</h2>
          <div class="pill-row">
            <span class="pill">${q1_business_overview || 'Not provided.'}</span>
          </div>
        </div>

        <div class="section">
          <h2>A Typical Shift</h2>
          <div class="pill-row">
            <span class="pill">${q2_daily_workflow || 'Not provided.'}</span>
          </div>
        </div>

        <div class="section">
          <h2>Key Bottlenecks</h2>
          <div class="pill-row">
            <span class="pill">${q3_bottlenecks || 'Not provided.'}</span>
          </div>
        </div>

        <div class="section">
          <h2>Current Systems &amp; Tools</h2>
          <div class="pill-row">
            <span class="pill">${q4_systems_tools || 'Not provided.'}</span>
          </div>
        </div>

        <div class="section">
          <h2>Desired Outcomes</h2>
          <div class="pill-row">
            <span class="pill">${q5_desired_outcomes || 'Not provided.'}</span>
          </div>
        </div>

        <div class="footer">
          <p>
            Suggested next step: reply to
            <a href="mailto:${user_email}">${user_email}</a>
            to schedule an introductory call and explore how ClinicIQ’s AI overlays can take admin off their shifts.
          </p>
          <p>
            This email was generated automatically from the ClinicIQ Solutions chat transcript.
          </p>
        </div>
      </div>
    </div>
  </div>
</body>
</html>
`;

// Return a single item for the next node (e.g. Email node)
return [
  {
    json: {
      to: `${reportRecipientName} <${user_email}>`,
      subject,
      html,
      // You can also pass the raw latest object along if useful:
      enquiry: latest,
    },
  },
];

